+          useFactory: () => ({
+            getViewportScrollPosition: () => ({top: scrollPosition}),
+          }),
+        },
+      ],
+    });
+
+    TestBed.compileComponents();
+  }));
+
+  beforeEach(inject([Overlay], (overlay: Overlay) => {
+    let overlayConfig = new OverlayConfig({scrollStrategy: overlay.scrollStrategies.close()});
