+
+      .cdk-virtual-scroll-orientation-horizontal .cdk-virtual-scroll-content-wrapper {
+        flex-direction: row;
+      }
+
+      .cdk-virtual-scroll-viewport {
+        background-color: #f5f5f5;
+      }
+
+      .item {
+        box-sizing: border-box;
+        border: 1px dashed #ccc;
+      }
+
+      .has-margin .item {
+        margin-bottom: 10px;
